usage() {
    cat <<'EOF'
Usage: bash scripts/HHH_new_pipeline.sh COMMAND

Generation (paid provider APIs):
  game-generate          Claude Sonnet 5 generator; GPT-5.6 Luna judge
  game-generate-check    Read-only preflight/status for game generation
  solo-generate          Claude Sonnet 5 generator; all three value pairs
  solo-generate-backfill Claude Sonnet 5; add one helpfulness/honesty scenario
  solo-filter            GPT-5.6 Luna judges all solo generation JSON files
  solo-topup-to-50       Resume Claude generation + paid GPT filtering until
                         every solo value pair has at least 50 kept scenarios

Balanced evaluation (50 kept cases per value pair):
  game-eval-mcq          Gemma 4 31B only
  game-eval-open         gateway Gemma focal; paid GPT user and judge
  game-eval-play         gateway Gemma focal; paid GPT fallback judge
  game-eval-qwen-mcq     Qwen 3.5 122B only
  game-eval-qwen-open    gateway Qwen focal; paid GPT user and judge
  game-eval-qwen-play    gateway Qwen focal; paid GPT fallback judge
  game-eval-gptoss-mcq   GPT-OSS 120B only
  game-eval-gptoss-open  gateway GPT-OSS focal; paid GPT user and judge
  game-eval-gptoss-play  gateway GPT-OSS focal; paid GPT fallback judge
  solo-eval-llama33-*    Llama 3.3 70B solo evals via OpenRouter (billed per token)
  solo-eval-maverick-*   Llama 4 Maverick solo evals via OpenRouter (billed per token)
  solo-eval-mcq          Gemma 4 31B only
  solo-eval-interactive  gateway Gemma; paid GPT user and judge
  solo-eval-qwen-mcq     Qwen 3.5 122B only
  solo-eval-qwen-interactive  gateway Qwen; paid GPT user and judge
  solo-eval-gptoss-mcq   GPT-OSS 120B only
  solo-eval-gptoss-interactive  gateway GPT-OSS; paid GPT user and judge

Prompt-steering (--steer-prompt value_sets/steering/HHH.txt) and repeated
open-ended (--rounds 5 --memory-k 1) variants of the above, writing distinct
output_name files into the same balanced50 directories:
  game-eval-{mcq,open,play}-steer            Gemma; steered
  game-eval-qwen-{mcq,open,play}-steer       Qwen 3.5 122B; steered
  game-eval-gptoss-{mcq,open,play}-steer     GPT-OSS 120B; steered
  game-eval-open-repeated                    Gemma; 5-round, mem-k=1 open-ended
  game-eval-qwen-open-repeated                Qwen 3.5 122B; 5-round, mem-k=1
  game-eval-gptoss-open-repeated              GPT-OSS 120B; 5-round, mem-k=1
  game-eval-open-counterpart[-<arm>]          Gemma 4 31B open-ended, simulated
  game-eval-maverick-open-counterpart[-<arm>] user names the other AI in its
  game-eval-qwen3235-open-counterpart[-<arm>] opening (<arm>: states[-stakes-*],
                                              stakes-*, steer; omit for baseline)
  solo-eval-{mcq,interactive}-steer          Gemma; steered
  solo-eval-qwen-{mcq,interactive}-steer     Qwen 3.5 122B; steered
  solo-eval-gptoss-{mcq,interactive}-steer   GPT-OSS 120B; steered

Other:
  solo-analyze           Analyze solo results; no API/model calls
  game-figures           Gemma value/summary figures from the game results; no API calls
  game-figures-qwen      Qwen value/summary figures; no API calls
  game-figures-gptoss    GPT-OSS value/summary figures; no API calls
  comparison-figures     Per-model game/solo and cross-model game figures; no API calls
  list                   Print this command/model map

Set GATEWAY_KEY_INDEX=1, 2, or 3 to select a gateway key (default: 1).
Each command uses a fixed, mode-specific output so safe resume checks cannot
confuse one evaluation mode with another.
EOF
}

if (( $# != 1 )); then
    usage >&2
    exit 2
fi

case "$1" in
    list)
        usage
        ;;
    game-generate)
        CONFIG_FILE="${GAME_GENERATE_CONFIG}" exec bash "${SCRIPT_DIR}/HHH_paper_bothAI_anthropic_batch_generation.sh"
        ;;
    game-generate-check)
        CONFIG_FILE="${GAME_GENERATE_CONFIG}" CHECK_ONLY=1 exec bash "${SCRIPT_DIR}/HHH_paper_bothAI_anthropic_batch_generation.sh"
        ;;
    solo-generate)
        CONFIG_FILE="${SOLO_GENERATE_CONFIG}" exec bash "${SCRIPT_DIR}/HHH_new_solo_anthropic_batch_generation.sh"
        ;;
    solo-generate-backfill)
        # shellcheck source=paid_env.sh
        source "${SCRIPT_DIR}/paid_env.sh"
        exec python -u -m conflictxgame.solo.generate_scenarios \
            --config "${SOLO_BACKFILL_CONFIG}"
        ;;
    solo-filter)
        # shellcheck source=paid_env.sh
        source "${SCRIPT_DIR}/paid_env.sh"
        shopt -s nullglob
        scenario_files=(data/HHH_new_solo_20260826_01/scenarios/*.json)
        if (( ${#scenario_files[@]} == 0 )); then
            echo "No solo scenario JSON files found; run solo-generate first." >&2
            exit 1
        fi
        for scenario_file in "${scenario_files[@]}"; do
            python -u -m conflictxgame.solo.filter_scenarios \
                --config "${SOLO_FILTER_CONFIG}" --input-file "${scenario_file}"
        done
        ;;
